window.__finlexDocLoaded(187,{"id":187,"articles":[{"id":4653,"no":"第一条","heading":"","text":"为了规范注册会计师执行集团审计时的特殊考虑，特别是涉及组成部分注册会计师的特殊考虑，制定本准则。","seq":0},{"id":4654,"no":"第二条","heading":"","text":"本准则规范集团审计的特定方面，其他审计准则同样适用于集团审计。","seq":1},{"id":4655,"no":"第三条","heading":"","text":"在执行非集团审计时，如果利用其他注册会计师的工作（如委托其他注册会计师对存放在偏远地点的存货实施监盘或对存放在偏远地点的固定资产实施检查），注册会计师可以根据具体情况遵守本准则的相关规定。","seq":2},{"id":4656,"no":"第四条","heading":"","text":"因法律法规要求或其他原因，组成部分注册会计师可能需要对组成部分财务报表发表审计意见。集团项目组可以决定利用组成部分注册会计师对组成部分财务报表发表审计意见所依据的审计证据，作为集团审计的审计证据，但仍需要遵守本准则的规定。","seq":3},{"id":4657,"no":"第五条","heading":"","text":"按照《中国注册会计师审计准则第1121号——对财务报表审计实施的质量管理》的规定，集团项目合伙人应当确保执行集团审计业务的人员（包括组成部分注册会计师）从整体上具备适当的胜任能力和必要素质，包括充足的时间。集团项目合伙人还需要对指导、监督集团项目组成员并复核其工作承担责任。","seq":4},{"id":4658,"no":"第六条","heading":"","text":"无论是集团项目组还是组成部分注册会计师对组成部分财务信息执行相关工作，集团项目合伙人都需要遵守《中国注册会计师审计准则第1121号——对财务报表审计实施的质量管理》的相关规定。当组成部分注册会计师对组成部分财务信息执行相关工作时，本准则有助于集团项目合伙人满足《中国注册会计师审计准则第1121号——对财务报表审计实施的质量管理》的要求。","seq":5},{"id":4659,"no":"第七条","heading":"","text":"审计风险取决于重大错报风险和检查风险。在集团审计中，审计风险包括组成部分注册会计师可能没有发现组成部分财务信息存在的错报（该错报导致集团财务报表发生重大错报）的风险，以及集团项目组可能没有发现该错报的风险。本准则规定了在组成部分注册会计师对组成部分财务信息实施风险评估程序和进一步审计程序时，集团项目组在确定参与组成部分注册会计师工作的性质、时间安排和范围时需要考虑的事项。集团项目组参与组成部分注册会计师工作的目的是为了获取充分、适当的审计证据，以作为形成集团财务报表审计意见的基础。 ## 第二章 定义","seq":6},{"id":4660,"no":"第八条","heading":"","text":"集团，是指由所有组成部分构成的整体，并且所有组成部分的财务信息包括在集团财务报表中。集团至少拥有一个以上的组成部分。","seq":7},{"id":4661,"no":"第九条","heading":"","text":"集团财务报表，是指包括一个以上组成部分财务信息的财务报表。集团财务报表也指没有母公司但处在同一控制下的各组成部分编制的财务信息所汇总生成的财务报表。","seq":8},{"id":4662,"no":"第十条","heading":"","text":"本准则所称适用的财务报告编制基础，是指适用于集团财务报表的财务报告编制基础。","seq":9},{"id":4663,"no":"第十一条","heading":"","text":"集团管理层，是指负责编制集团财务报表的管理层。","seq":10},{"id":4664,"no":"第十二条","heading":"","text":"集团层面控制，是指集团管理层设计、执行和维护的与集团财务报告相关的控制。","seq":11},{"id":4665,"no":"第十三条","heading":"","text":"集团审计，是指对集团财务报表进行的审计。","seq":12},{"id":4666,"no":"第十四条","heading":"","text":"集团审计意见，是指对集团财务报表发表的审计意见。","seq":13},{"id":4667,"no":"第十五条","heading":"","text":"集团项目合伙人，是指会计师事务所中负责某项集团审计业务及其执行，并代表会计师事务所在对集团财务报表出具的审计报告上签字的合伙人。如果集团项目合伙人以外的其他注册会计师在对集团财务报表出具的审计报告上签字，本准则对集团项目合伙人的规定也适用于该签字注册会计师。如果联合注册会计师执行集团审计，联合项目合伙人及其项目组整体上构成集团项目合伙人和集团项目组。但是，本准则并不规范联合注册会计师之间的关系，或参与联合审计的一方注册会计师执行的工作与另一方注册会计师执行的工作之间的关系。","seq":14},{"id":4668,"no":"第十六条","heading":"","text":"集团项目组，是指参与集团审计的，包括集团项目合伙人在内的所有合伙人和员工。集团项目组负责制定集团总体审计策略，与组成部分注册会计师沟通，针对合并过程执行相关工作，并评价根据审计证据得出的结论，作为形成集团财务报表审计意见的基础。","seq":15},{"id":4669,"no":"第十七条","heading":"","text":"组成部分，是指某一实体或某项业务活动，其财务信息由集团或组成部分管理层编制并应包括在集团财务报表中。","seq":16},{"id":4670,"no":"第十八条","heading":"","text":"重要组成部分，是指集团项目组识别出的具有下列特征之一的组成部分： **（一）单个组成部分对集团具有财务重大性；** （二）由于单个组成部分的特定性质或情况，可能存在导致集团财务报表发生重大错报的特别风险。","seq":17},{"id":4671,"no":"第十九条","heading":"","text":"组成部分管理层，是指负责编制组成部分财务信息的管理层。","seq":18},{"id":4672,"no":"第二十条","heading":"","text":"组成部分注册会计师，是指基于集团审计目的，按照集团项目组的要求，对组成部分财务信息执行相关工作的注册会计师。","seq":19},{"id":4673,"no":"第二十一条","heading":"","text":"组成部分重要性，是指集团项目组为组成部分确定的重要性。","seq":20},{"id":4674,"no":"第二十二条","heading":"","text":"合并过程，是指： （一）通过合并、比例合并、权益法或成本法，在集团财务报表中对组成部分财务信息进行确认、计量与列报； （二）对没有母公司但处在同一控制下的各组成部分编制的财务信息进行汇总。 ## 第三章 目标","seq":21},{"id":4675,"no":"第二十三条","heading":"","text":"注册会计师的目标是： **（一）确定是否担任集团审计的注册会计师；** （二）如果担任集团审计的注册会计师，就组成部分注册会计师对组成部分财务信息执行工作的范围、时间安排和发现的问题，与组成部分注册会计师进行清晰的沟通；针对组成部分财务信息和合并过程，获取充分、适当的审计证据，以对集团财务报表是否在所有重大方面按照适用的财务报告编制基础编制发表审计意见。 ## 第四章 要求 ### 第一节 责任","seq":22},{"id":4676,"no":"第二十四条","heading":"","text":"集团项目合伙人应当按照职业准则和适用的法律法规的规定，负责指导、监督和执行集团审计业务，并确定出具的审计报告是否适合具体情况。注册会计师对集团财务报表出具的审计报告不应提及组成部分注册会计师，除非法律法规另有规定。如果法律法规要求在审计报告中提及组成部分注册会计师，审计报告应当指明，这种提及并不减轻集团项目合伙人及其所在的会计师事务所对集团审计意见承担的责任。 ### 第二节 集团审计业务的承接与保持","seq":23},{"id":4677,"no":"第二十五条","heading":"","text":"在具体运用《中国注册会计师审计准则第1121号——对财务报表审计实施的质量管理》时，集团项目合伙人应当确定是否能够合理预期获取与合并过程和组成部分财务信息相关的充分、适当的审计证据，以作为形成集团审计意见的基础。因此，集团项目组应当了解集团及其环境、集团组成部分及其环境，以足以识别可能的重要组成部分。如果组成部分注册会计师对重要组成部分财务信息执行相关工作，集团项目合伙人应当评价集团项目组参与组成部分注册会计师工作的程度是否足以获取充分、适当的审计证据。","seq":24},{"id":4678,"no":"第二十六条","heading":"","text":"如果集团项目合伙人认为由于集团管理层施加的限制，使集团项目组不能获取充分、适当的审计证据，由此产生的影响可能导致对集团财务报表发表无法表示意见，集团项目合伙人应当视具体情况采取下列措施： （一）如果是新业务，拒绝接受业务委托，如果是连续审计业务，在法律法规允许的情况下，解除业务约定； （二）如果法律法规禁止注册会计师拒绝接受业务委托，或者注册会计师不能解除业务约定，在可能的范围内对集团财务报表实施审计，并对集团财务报表发表无法表示意见。","seq":25},{"id":4679,"no":"第二十七条","heading":"","text":"集团项目合伙人应当按照《中国注册会计师审计准则第1111号——就审计业务约定条款达成一致意见》的规定，就集团审计业务约定条款与管理层或治理层（如适用）达成一致意见。 ### 第三节 总体审计策略和具体审计计划","seq":26},{"id":4680,"no":"第二十八条","heading":"","text":"集团项目组应当按照《中国注册会计师审计准则第1201号——计划审计工作》的规定，制定集团总体审计策略和具体审计计划。","seq":27},{"id":4681,"no":"第二十九条","heading":"","text":"集团项目合伙人应当复核集团总体审计策略和具体审计计划。 ### 第四节 了解集团及其环境、集团组成部分及其环境","seq":28},{"id":4682,"no":"第三十条","heading":"","text":"注册会计师应当通过了解被审计单位及其环境、适用的财务报告编制基础和被审计单位内部控制体系，识别和评估财务报表重大错报风险。集团项目组应当： （一）在业务承接或保持阶段获取信息的基础上，进一步了解集团及其环境、集团组成部分及其环境，包括集团层面控制； **（二）了解合并过程，包括集团管理层向组成部分下达的指令。**","seq":29},{"id":4683,"no":"第三十一条","heading":"","text":"集团项目组应当对集团及其环境、集团组成部分及其环境获取充分的了解，以足以： **（一）确认或修正最初识别的重要组成部分；** **（二）评估由于舞弊或错误导致集团财务报表发生重大错报的风险。** ### 第五节 了解组成部分注册会计师","seq":30},{"id":4684,"no":"第三十二条","heading":"","text":"如果计划要求组成部分注册会计师执行组成部分财务信息的相关工作，集团项目组应当了解下列事项： （一）组成部分注册会计师是否了解并将遵守与集团审计相关的职业道德要求，特别是独立性要求； **（二）组成部分注册会计师是否具备专业胜任能力；** （三）集团项目组参与组成部分注册会计师工作的程度是否足以获取充分、适当的审计证据； **（四）组成部分注册会计师是否处于积极的监管环境中。**","seq":31},{"id":4685,"no":"第三十三条","heading":"","text":"如果组成部分注册会计师不符合与集团审计相关的独立性要求，或集团项目组对本准则第三十二条第（一）项至第（三）项所列事项存有重大疑虑，集团项目组应当就组成部分财务信息获取充分、适当的审计证据，而不应要求组成部分注册会计师对组成部分财务信息执行相关工作。 ### 第六节 重要性","seq":32},{"id":4686,"no":"第三十四条","heading":"","text":"集团项目组应当确定与重要性相关的下列事项： （一）在制定集团总体审计策略时，确定集团财务报表整体的重要性。 （二）根据集团的特定情况，如果存在特定类别的交易、账户余额或披露，其发生的错报金额低于集团财务报表整体的重要性，但合理预期将影响财务报表使用者依据集团财务报表作出的经济决策，则确定适用于这些交易、账户余额或披露的一个或多个重要性水平。 （三）如果组成部分注册会计师对组成部分财务信息实施审计或审阅，基于集团审计目的，为这些组成部分确定组成部分重要性。为将未更正和未发现错报的汇总数超过集团财务报表整体的重要性的可能性降至适当的低水平，组成部分重要性应当低于集团财务报表整体的重要性。 （四）设定临界值，不能将超过该临界值的错报视为对集团财务报表明显微小的错报。","seq":33},{"id":4687,"no":"第三十五条","heading":"","text":"如果基于集团审计目的，由组成部分注册会计师对组成部分财务信息执行审计工作，集团项目组应当评价在组成部分层面确定的实际执行的重要性的适当性。","seq":34},{"id":4688,"no":"第三十六条","heading":"","text":"如果因法律法规或其他原因要求对组成部分进行审计，并且集团项目组决定利用该审计为集团审计提供审计证据，集团项目组应当确定下列方面是否符合本准则的规定： **（一）组成部分财务报表整体的重要性；** **（二）组成部分层面实际执行的重要性。** ### 第七节 针对评估的风险采取的应对措施","seq":35},{"id":4689,"no":"第三十七条","heading":"","text":"注册会计师应当针对评估的财务报表重大错报风险设计和实施恰当的应对措施。对于组成部分财务信息，集团项目组应当确定由其亲自执行或由组成部分注册会计师代为执行的相关工作的类型。集团项目组还应当确定参与组成部分注册会计师工作的性质、时间安排和范围。","seq":36},{"id":4690,"no":"第三十八条","heading":"","text":"在确定对合并过程或组成部分财务信息拟执行的工作的性质、时间安排和范围时，如果预期集团层面控制运行有效，或者仅实施实质性程序不能提供认定层次的充分、适当的审计证据，集团项目组应当测试或要求组成部分注册会计师测试这些控制运行的有效性。","seq":37},{"id":4691,"no":"第三十九条","heading":"","text":"就集团而言，对于具有财务重大性的单个组成部分，集团项目组或代表集团项目组的组成部分注册会计师应当运用该组成部分的重要性，对组成部分财务信息实施审计。","seq":38},{"id":4692,"no":"第四十条","heading":"","text":"对由于其特定性质或情况，可能存在导致集团财务报表发生重大错报的特别风险的重要组成部分，集团项目组或代表集团项目组的组成部分注册会计师应当执行下列一项或多项工作： **（一）使用组成部分重要性对组成部分财务信息实施审计；** （二）针对与可能导致集团财务报表发生重大错报的特别风险相关的一个或多个账户余额、一类或多类交易或披露事项实施审计； （三）针对可能导致集团财务报表发生重大错报的特别风险实施特定的审计程序。","seq":39},{"id":4693,"no":"第四十一条","heading":"","text":"对于不重要的组成部分，集团项目组应当在集团层面实施分析程序。","seq":40},{"id":4694,"no":"第四十二条","heading":"","text":"如果集团项目组认为执行下列工作不能获取形成集团审计意见所依据的充分、适当的审计证据，应当采取本条第二款规定的措施： **（一）对重要组成部分财务信息执行的工作；** **（二）对集团层面控制和合并过程执行的工作；** **（三）在集团层面实施的分析程序。** 集团项目组应当选择某些不重要的组成部分，并对已选择的组成部分财务信息亲自执行或由代表集团项目组的组成部分注册会计师执行下列一项或多项工作： **（一）使用组成部分重要性对组成部分财务信息实施审计；** **（二）对一个或多个账户余额、一类或多类交易或披露实施审计；** **（三）使用组成部分重要性对组成部分财务信息实施审阅；** **（四）实施特定程序。** 集团项目组应当在一段时间之后更换所选择的组成部分。","seq":41},{"id":4695,"no":"第四十三条","heading":"","text":"如果组成部分注册会计师对重要组成部分财务信息执行审计，集团项目组应当参与组成部分注册会计师实施的风险评估程序，以识别导致集团财务报表发生重大错报的特别风险。集团项目组参与的性质、时间安排和范围受其对组成部分注册会计师所了解情况的影响，但至少应当包括： （一）与组成部分注册会计师或组成部分管理层讨论对集团而言重要的组成部分业务活动； （二）与组成部分注册会计师讨论由于舞弊或错误导致组成部分财务信息发生重大错报的可能性； （三）复核组成部分注册会计师对识别出的导致集团财务报表发生重大错报的特别风险形成的审计工作底稿。审计工作底稿可以采用备忘录的形式，反映组成部分注册会计师针对识别出的特别风险得出的结论。","seq":42},{"id":4696,"no":"第四十四条","heading":"","text":"如果在由组成部分注册会计师执行相关工作的组成部分内，识别出导致集团财务报表发生重大错报的特别风险，集团项目组应当评价针对识别出的特别风险拟实施的进一步审计程序的恰当性。根据对组成部分注册会计师的了解，集团项目组应当确定是否有必要参与进一步审计程序。 ### 第八节 合并过程","seq":43},{"id":4697,"no":"第四十五条","heading":"","text":"根据本准则第三十条的规定，集团项目组应当了解集团层面的控制和合并过程，包括集团管理层向组成部分下达的指令。根据本准则第三十八条的规定，如果对合并过程执行工作的性质、时间安排和范围基于预期集团层面控制有效运行，或者仅实施实质性程序不能提供认定层次的充分、适当的审计证据，集团项目组应当亲自测试或要求组成部分注册会计师代为测试集团层面控制运行的有效性。","seq":44},{"id":4698,"no":"第四十六条","heading":"","text":"集团项目组应当针对合并过程设计和实施进一步审计程序，以应对评估的、由合并过程导致的集团财务报表发生重大错报的风险。设计和实施的进一步审计程序应当包括评价所有组成部分是否均已包括在集团财务报表中。","seq":45},{"id":4699,"no":"第四十七条","heading":"","text":"集团项目组应当评价合并调整和重分类事项的适当性、完整性和准确性，并评价是否存在舞弊风险因素或可能存在管理层偏向的迹象。","seq":46},{"id":4700,"no":"第四十八条","heading":"","text":"如果组成部分财务信息没有按照集团财务报表采用的会计政策编制，集团项目组应当评价组成部分财务信息是否已得到适当调整，以满足编制和列报集团财务报表的要求。","seq":47},{"id":4701,"no":"第四十九条","heading":"","text":"集团项目组应当确定，组成部分注册会计师按照本准则第五十四条的规定进行的沟通中提及的财务信息是否就是包括在集团财务报表中的财务信息。","seq":48},{"id":4702,"no":"第五十条","heading":"","text":"如果集团财务报表包括的组成部分财务报表的报告期末不同于集团财务报表，集团项目组应当评价是否已按照适用的财务报告编制基础对这些财务报表作出恰当调整。 ### 第九节 期后事项","seq":49},{"id":4703,"no":"第五十一条","heading":"","text":"如果集团项目组或组成部分注册会计师对组成部分财务信息实施审计，集团项目组或组成部分注册会计师应当实施审计程序，以识别组成部分自组成部分财务信息日至对集团财务报表出具审计报告日之间发生的、可能需要在集团财务报表中调整或披露的事项。","seq":50},{"id":4704,"no":"第五十二条","heading":"","text":"如果组成部分注册会计师执行组成部分财务信息审计以外的工作，集团项目组应当要求组成部分注册会计师告知其注意到的、可能需要在集团财务报表中调整或披露的期后事项。 ### 第十节 与组成部分注册会计师的沟通","seq":51},{"id":4705,"no":"第五十三条","heading":"","text":"集团项目组应当及时向组成部分注册会计师通报工作要求。通报的内容应当明确组成部分注册会计师应执行的工作和集团项目组对其工作的利用，以及组成部分注册会计师与集团项目组沟通的形式和内容。通报的内容还应当包括： （一）在组成部分注册会计师知悉集团项目组将利用其工作的前提下，要求组成部分注册会计师确认其将配合集团项目组的工作。 **（二）与集团审计相关的职业道德要求，特别是独立性要求。** （三）在对组成部分财务信息实施审计或审阅的情况下，组成部分的重要性和针对特定类别的交易、账户余额或披露采用的一个或多个重要性水平（如适用）以及临界值，超过临界值的错报不能视为对集团财务报表明显微小的错报。 （四）识别出的与组成部分注册会计师工作相关的、由于舞弊或错误导致集团财务报表发生重大错报的特别风险。集团项目组应当要求组成部分注册会计师及时沟通所有识别出的、在组成部分内的其他由于舞弊或错误可能导致集团财务报表发生重大错报的特别风险，以及组成部分注册会计师针对这些特别风险采取的应对措施。 （五）集团管理层编制的关联方清单和集团项目组知悉的任何其他关联方。集团项目组应当要求组成部分注册会计师及时沟通集团管理层或集团项目组以前未识别出的关联方。集团项目组应当确定是否需要将新识别的关联方告知其他组成部分注册会计师。","seq":52},{"id":4706,"no":"第五十四条","heading":"","text":"集团项目组应当要求组成部分注册会计师沟通与得出集团审计结论相关的事项。沟通的内容应当包括： （一）组成部分注册会计师是否已遵守与集团审计相关的职业道德要求，包括对独立性和专业胜任能力的要求； **（二）组成部分注册会计师是否已遵守集团项目组的要求；** （三）指出作为组成部分注册会计师出具报告对象的组成部分财务信息； （四）因违反法律法规而可能导致集团财务报表发生重大错报的信息； （五）组成部分财务信息中未更正错报的清单（清单不必包括低于集团项目组通报的临界值且明显微小的错报）； **（六）表明可能存在管理层偏向的迹象；** **（七）描述识别出的组成部分层面值得关注的内部控制缺陷；** （八）组成部分注册会计师向组成部分治理层已通报或拟通报的其他重大事项，包括涉及组成部分管理层、在组成部分层面内部控制中承担重要职责的员工以及其他人员（在舞弊行为导致组成部分财务信息出现重大错报的情况下）的舞弊或舞弊嫌疑； （九）可能与集团审计相关或者组成部分注册会计师期望集团项目组加以关注的其他事项，包括在组成部分注册会计师要求组成部分管理层提供的书面声明中指出的例外事项； **（十）组成部分注册会计师的总体发现、得出的结论和形成的意见。** ### 第十一节 评价审计证据的充分性和适当性","seq":53},{"id":4707,"no":"第五十五条","heading":"","text":"集团项目组应当评价与组成部分注册会计师的沟通。集团项目组应当： （一）与组成部分注册会计师、组成部分管理层或集团管理层（如适用）讨论在评价过程中发现的重大事项； （二）确定是否有必要复核组成部分注册会计师审计工作底稿的相关部分。","seq":54},{"id":4708,"no":"第五十六条","heading":"","text":"如果认为组成部分注册会计师的工作不充分，集团项目组应当确定需要实施哪些追加的程序，以及这些程序是由组成部分注册会计师还是由集团项目组实施。","seq":55},{"id":4709,"no":"第五十七条","heading":"","text":"注册会计师应当获取充分、适当的审计证据，将审计风险降至可接受的低水平，从而得出合理的结论以作为形成审计意见的基础。集团项目组应当评价，通过对合并过程实施的审计程序以及由集团项目组和组成部分注册会计师对组成部分财务信息执行的工作，是否已获取充分、适当的审计证据，作为形成集团审计意见的基础。","seq":56},{"id":4710,"no":"第五十八条","heading":"","text":"集团项目合伙人应当评价未更正错报（无论该错报是由集团项目组识别出的还是由组成部分注册会计师告知的）和未能获取充分、适当的审计证据的情况对集团审计意见的影响。 ### 第十二节 与集团管理层和集团治理层的沟通","seq":57},{"id":4711,"no":"第五十九条","heading":"","text":"集团项目组应当按照《中国注册会计师审计准则第1152号——向治理层和管理层通报内部控制缺陷》的规定，确定哪些识别出的内部控制缺陷需要向集团治理层和集团管理层通报。在确定通报的内容时，集团项目组应当考虑： **（一）集团项目组识别出的集团层面内部控制缺陷；** **（二）集团项目组识别出的组成部分层面内部控制缺陷；** **（三）组成部分注册会计师提请集团项目组关注的内部控制缺陷。**","seq":58},{"id":4712,"no":"第六十条","heading":"","text":"如果集团项目组识别出舞弊或组成部分注册会计师提请集团项目组关注舞弊，或者有关信息表明可能存在舞弊，集团项目组应当及时向适当层级的集团管理层通报，以便管理层告知主要负责防止和发现舞弊事项的人员。","seq":59},{"id":4713,"no":"第六十一条","heading":"","text":"因法律法规要求或其他原因，组成部分注册会计师可能需要对组成部分财务报表发表审计意见。在这种情况下，集团项目组应当要求集团管理层告知组成部分管理层其尚未知悉的、集团项目组注意到的可能对组成部分财务报表产生重要影响的事项。如果集团管理层拒绝向组成部分管理层通报该事项，集团项目组应当与集团治理层进行讨论。如果该事项仍未得到解决，集团项目组在遵守法律法规和职业准则有关保密要求的前提下，应当考虑是否建议组成部分注册会计师在该事项得到解决之前，不对组成部分财务报表出具审计报告。","seq":60},{"id":4714,"no":"第六十二条","heading":"","text":"除《中国注册会计师审计准则第1151号——与治理层的沟通》和其他审计准则要求沟通的事项外，集团项目组还应当与集团治理层沟通下列事项： **（一）对组成部分财务信息拟执行工作的类型的概述；** （二）在组成部分注册会计师对重要组成部分财务信息拟执行的工作中，集团项目组计划参与其工作的性质的概述； （三）对组成部分注册会计师的工作作出的评价，引起集团项目组对其工作质量产生疑虑的情形； （四）集团审计受到的限制，如集团项目组接触某些信息受到的限制； （五）涉及集团管理层、组成部分管理层、在集团层面控制中承担重要职责的员工以及其他人员（在舞弊行为导致集团财务报表出现重大错报的情况下）的舞弊或舞弊嫌疑。 ### 第十三节 审计工作底稿","seq":61},{"id":4715,"no":"第六十三条","heading":"","text":"集团项目组应当就下列事项形成审计工作底稿： （一）对组成部分的分析，指明重要组成部分以及对组成部分财务信息执行工作的类型； （二）对于重要组成部分，集团项目组参与该组成部分注册会计师工作的性质、时间安排和范围，如果适用，还包括集团项目组对组成部分注册会计师审计工作底稿的相关部分进行的复核以及由此得出的结论； （三）集团项目组与组成部分注册会计师就集团项目组提出的工作要求的书面沟通函件。 ## 第五章 附则","seq":62},{"id":4716,"no":"第六十四条","heading":"","text":"本准则自2023年7月1日起施行。","seq":63}]});
